"""Session glue for the shared Amane palettes and Noctalia's native controls."""
import fcntl
import hashlib
import json
import os
from pathlib import Path
import random
import subprocess
import sys
import tempfile

CONFIG = Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
CACHE = Path(os.environ.get("XDG_CACHE_HOME", Path.home() / ".cache")) / "noctalia/desktop"
AMANE = CONFIG / "amane"


def write(path, text):
    """Replace only our generated file, without publishing partial TOML."""
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_text() == text:
        return
    with tempfile.NamedTemporaryFile(mode="w", dir=path.parent, delete=False) as stream:
        stream.write(text)
        temporary = stream.name
    os.replace(temporary, path)


def read(path, default):
    return path.read_text().strip() if path.exists() else default


def msg(*args):
    return subprocess.run(["noctalia", "msg", *args], capture_output=True, text=True, timeout=5)


def wallpaper_directory(theme, metadata):
    source = Path.home() / "Pictures/Wallpapers" / metadata["wallpaperDir"]
    allow_nsfw = read(AMANE / ".nsfw-enabled", "false") == "true"
    directory = CACHE / "wallpapers" / (theme + ("-all" if allow_nsfw else "-sfw"))
    directory.mkdir(parents=True, exist_ok=True)
    links = {}
    if source.is_dir():
        for path in source.rglob("*"):
            if path.is_file() and path.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp"):
                if allow_nsfw or "[NSFW]" not in path.name:
                    key = hashlib.sha256(str(path).encode()).hexdigest()[:16]
                    links[key + path.suffix.lower()] = path
    for old in directory.iterdir():
        if old.is_symlink() and old.name not in links:
            old.unlink()
    for name, path in links.items():
        target = directory / name
        if not target.is_symlink():
            target.symlink_to(path)
    return directory, sorted(directory / name for name in links)


def sync():
    themes = json.loads((AMANE / "themes/themes.json").read_text())
    theme = read(AMANE / ".current-theme", "pastelglow")
    metadata = themes[theme]
    palette = json.loads((CONFIG / "noctalia/palettes" / (theme + ".json")).read_text())["dark"]
    bottom = read(AMANE / ".bar-position", "top") == "bottom"
    mode = "light" if metadata["light"] else "dark"
    directory, wallpapers = wallpaper_directory(theme, metadata)
    write(CONFIG / "noctalia/90-amane.toml", f'''# Generated by noctalia-desktop from the shared desktop state.
[theme]
source = "custom"
custom_palette = {json.dumps(theme)}
mode = "{mode}"
[wallpaper]
directory = {json.dumps(str(directory))}
directory_light = ""
directory_dark = ""
[bar.main]
position = "{'bottom' if bottom else 'top'}"
margin_ends = {0 if bottom else 6}
margin_edge = {0 if bottom else 6}
radius = {0 if bottom else 12}
''')
    write(CACHE / "appearance.toml", f'''# Generated by noctalia-desktop.
[layout]
gap = {0 if bottom else 6}
[appearance]
border_width = {0 if bottom else 2}
corner_radius = {0 if bottom else 12}
[appearance.shadow]
enabled = {str(not bottom).lower()}
[[window_rule]]
match.is_focused = false
opacity = {1.0 if bottom else 0.95}
''')
    write(CACHE / "theme.toml", f'''# Generated from the shared Amane palette.
[colors]
background = "{palette['surface']}"
text_primary = "{palette['on_surface']}"
text_muted = "{palette['on_surface_variant']}"
accent_primary = "{palette['primary']}"
accent_secondary = "{palette['secondary']}"
warning = "{palette['tertiary']}"
error = "{palette['error']}"
shadow = "{palette['shadow']}aa"
[colors.border]
focused = "{palette['primary']}"
unfocused = "{palette['surface_container']}"
''')
    # IPC clears earlier GUI overrides for these two palette choices.
    current = msg("color-scheme-get")
    if current.returncode == 0:
        if current.stdout.strip() != "custom " + theme:
            msg("color-scheme-set", "custom", theme)
        if msg("theme-mode-get").stdout.strip() != mode:
            msg("theme-mode-set", mode)
        # Keep a selection in the curated directory; remove a now-excluded image
        # immediately when the filter or palette changes.
        current_wallpaper = msg("wallpaper-get").stdout.strip()
        if current_wallpaper not in {str(path) for path in wallpapers}:
            msg("wallpaper-set", str(random.choice(wallpapers)) if wallpapers else "color:" + palette["surface"])


def main():
    command = sys.argv[1]
    if command == "theme-changed":
        selection = msg("color-scheme-get")
        if selection.returncode != 0:
            return
        source, _, theme = selection.stdout.strip().partition(" ")
        themes = json.loads((AMANE / "themes/themes.json").read_text())
        if source == "custom" and theme in themes and theme != read(AMANE / ".current-theme", "pastelglow"):
            subprocess.Popen(["bash", str(AMANE / "themes/switch-theme.sh"), theme])
        return
    CACHE.mkdir(parents=True, exist_ok=True)
    with (CACHE / "sync.lock").open("w") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if command == "bar":
            write(AMANE / ".bar-position", "top\n" if read(AMANE / ".bar-position", "top") == "bottom" else "bottom\n")
        elif command == "nsfw":
            enabled = read(AMANE / ".nsfw-enabled", "false") != "true"
            write(AMANE / ".nsfw-enabled", str(enabled).lower() + "\n")
        elif command != "sync":
            raise ValueError("Expected sync, theme-changed, bar or nsfw")
        sync()


if __name__ == "__main__":
    main()
